import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import gemmi
import pandas as pd
from typing import Tuple
import itertools
import glob
import os

### Contains necessary functions for the analysis

def load_confidences(path):
    """Load confidence metrics from a JSON file generated by AF3.
    Args:
        path (str): Path to the JSON file containing confidence metrics.
    Returns:
        tuple: A tuple containing PAE, contact probabilities, chain IDs, and residue IDs."""
    with open(path, "r") as f:
        conf = json.load(f)
    
    pae = np.array(conf["pae"]) # N x N
    contact_probs = np.array(conf["contact_probs"]) # N x N
    chain_ids = np.array(conf["token_chain_ids"]) # N 
    res_ids = np.array(conf["token_res_ids"]) # N

    return pae, contact_probs, chain_ids, res_ids

def load_structure_and_plddt(path: str) -> Tuple[gemmi.Structure, pd.DataFrame]:
    """Load a structure from a CIF file and extract pLDDT scores into a DataFrame.
    Args:
        path (str): Path to the CIF file containing the structure.
    Returns:
        Tuple[gemmi.Structure, pd.DataFrame]: A tuple containing the loaded structure and the pLDDT DataFrame."""
    # Load the structure using gemmi
    structure = gemmi.read_structure(path)

    records = []
    for model_idx, model in enumerate(structure):
        for chain in model:
            chain_id = chain.name
            for res in chain:
                b_vals = []
                for atom in res:
                    if atom.element.name == "H":  # Exclude hydrogens
                        continue
                    b = atom.b_iso # b can be 0.0 if unset; keep it but skip NaN/None
                    if b is None or b != b: # Check for NaN
                        continue
                    b_vals.append(float(b))
                
                if not b_vals:
                    continue  # Skip residues with no valid B-factors

                res_plddt = float(np.mean(b_vals))
                  # Average B-factor as pLDDT

                seqnum = res.seqid.num
                icode = res.seqid.icode
                icode = "" if not icode or icode == "\x00" else icode

                records.append({
                    "model_index": model_idx,
                    "chain": chain_id,
                    "residue_name": res.name,
                    "residue_id": seqnum,
                    "icode": icode,
                    "plddt": res_plddt
                })

    
    df = pd.DataFrame(records)
    if not df.empty: # sort by model, chain, residue_id, then insertion code
        df = df.sort_values(["model_index", "chain", "residue_id", "icode"]).reset_index(drop=True)
    return structure, df


def get_chain_ranges(chain_ids):
    """Get the start and end residue indices for each chain based on chain IDs.
    Args:
        chain_ids (np.ndarray): An array of chain IDs corresponding to each residue.
        """
    chain_order = [cid for cid, _ in itertools.groupby(chain_ids)]
    ranges = {}
    i = 0
    for cid in chain_order:
        count = np.sum(chain_ids == cid)
        ranges[cid] = (i, i + count)
        i += count
    return ranges

def interface_mean_pae(pae, ranges, chainA, chainB):
    """
    extract interface confidence features.
    """
    a_start, a_end = ranges[chainA]
    b_start, b_end = ranges[chainB]

    block_ab = pae[a_start:a_end, b_start:b_end]
    block_ba = pae[b_start:b_end, a_start:a_end]

    return float(block_ab.mean()), float(block_ba.mean())

def interface_contact_score(contact_probs, ranges, chainA, chainB):
    """
    extract interface contact probability (AF3-specific).
    """
    a_start, a_end = ranges[chainA]
    b_start, b_end = ranges[chainB]

    block_ab = contact_probs[a_start:a_end, b_start:b_end]

    return {
        "mean_contact_prob": float(block_ab.mean()),
        "max_contact_prob": float(block_ab.max()),
        "sum_contact_prob": float(block_ab.sum())
    }

def interface_plddt(plddt_df, contacts_df):
    """
    extract interface pLDDT by averaging the pLDDT of residues involved in predicted contacts across the interface.
    """
    ids = pd.unique(
        contacts_df[["chain_i", "resid_i"]].apply(tuple,axis=1).tolist() + 
        contacts_df[["chain_j", "resid_j"]].apply(tuple,axis=1).tolist()
    )

    mask = plddt_df.apply(lambda r: (r["chain"], r["residue_id"]) in ids, axis=1)
    return float(plddt_df.loc[mask, "plddt"].mean())


def find_real_confidences_json(complex_dir):
    """
    Return the correct confidences.json file for an AF3 prediction
    by checking which JSON actually contains PAE/contact data.
    """
    candidates = glob.glob(os.path.join(complex_dir, "*confidences*.json"))
    if len(candidates) == 0:
        return None
    
    real_candidates = []
    for path in candidates:
        try:
            with open(path) as f:
                js = json.load(f) 
                # the real AF3 confidences.json always contains at least one of these:
                if ("pae" in js) or ("contact_probs" in js):
                    real_candidates.append(path)
        except Exception as e:
            print(f"Error reading {path}: {e}")
            continue
    
    if len(real_candidates) == 0:
        return None
    
    if len(real_candidates) > 1:
        print("Warning: more than one real confidences file found:", real_candidates)
        real_candidates = sorted(real_candidates, key=lambda p: os.path.getsize(p), reverse=True)

    return real_candidates[0]

def find_file(folder, pattern):
    matches = glob.glob(os.path.join(folder, pattern))
    if len(matches) == 0:
        return None
    if len(matches) > 1:
        print(f"Warning: Multiple files found for pattern {pattern} in folder {folder}. Using the first one.")
    return matches[0]
